// ❌ 不要传 mediaInfo（会报错）
// const data = await telegram.downloadAsBuffer(msg.mediaInfo); // Error!
// ✅ 改用 downloadMedia，或先取 fileId 字符串
const data = await telegram.downloadMedia(msg.mediaInfo.fileId, chatId, msg.id, msg.mediaInfo.uniqueFileId);
